    "code": "// currency class using  a single data member\r\n// (amount) represent an instance\r\n\r\n#ifndef currency_\r\n#define currency_\r\n\r\n#include <iostream>\r\n#include \"myExceptions.h\"\r\n\r\nusing namespace std;\r\n\r\nenum signType {plus, minus};\r\n\r\nclass currency \r\n{\r\n   public:\r\n      // constructor\r\n      currency(signType theSign = plus,\r\n               unsigned long theDollars = 0,\r\n               unsigned int theCents = 0);\r\n      // destructor\r\n      ~currency() {}\r\n      void setValue(signType, unsigned long, unsigned int);\r\n      void setValue(double);\r\n      signType getSign() const\r\n        {if (amount < 0) return minus;\r\n         else return plus;}\r\n      unsigned long getDollars() const\r\n        {if (amount < 0) return (-amount) / 100;\r\n         else return amount / 100;}\r\n      unsigned int getCents() const\r\n        {if (amount < 0) return -amount - getDollars() * 100;\r\n         else return amount - getDollars() * 100;}\r\n      currency add(const currency&) const;\r\n      currency& increment(const currency& x)\r\n        {amount += x.amount; return *this;}\r\n      void output() const;\r\n   private:\r\n      long amount;\r\n};\r\n\r\ncurrency::currency(signType theSign, unsigned long theDollars,\r\n                                     unsigned int theCents)\r\n{// Create a currency object.\r\n   setValue(theSign, theDollars, theCents);\r\n}\r\n\r\nvoid currency::setValue(signType theSign, unsigned long theDollars,\r\n                                          unsigned int theCents)\r\n{// Set currency value.\r\n   if (theCents > 99)\r\n       // too many cents\r\n       throw illegalParameterValue(\"Cents should be < 100\");\r\n   \r\n   amount = theDollars * 100 + theCents;\r\n   if (theSign == minus) amount = -amount;\r\n}\r\n   \r\nvoid currency::setValue(double theAmount)\r\n{// Set currency value.\r\n   if (theAmount < 0)\r\n      amount = (long) ((theAmount - 0.001) * 100);\r\n   else\r\n      amount = (long) ((theAmount + 0.001) * 100);\r\n            // 2 decimal digits only\r\n}\r\n\r\ncurrency currency::add(const currency& x) const\r\n{// Add x and *this.\r\n  currency y;\r\n  y.amount = amount + x.amount;\r\n  return y;\r\n}\r\n\r\nvoid currency::output() const\r\n{// Output currency value.\r\n   long theAmount = amount;\r\n   if (theAmount < 0) {cout << '-';\r\n                       theAmount = -theAmount;}\r\n   long dollars = theAmount / 100; // dollars\r\n   cout << '$' << dollars << '.';\r\n   int cents = theAmount - dollars * 100; // cents\r\n   if (cents < 10) cout << '0';\r\n   cout << cents;\r\n}\r\n\r\n#endif\r\n\r\n"
