    "code": "// output all permutations of n elements\r\n\r\n#include <iostream>\r\n#include <algorithm> // has copy\r\n\r\nusing namespace std;\r\n\r\ntemplate<class T>\r\nvoid permutations(T list[], int k, int m)\r\n{// Generate all permutations of list[k:m].\r\n // Assume k <= m.\r\n   int i;\r\n   if (k == m) {// list[k:m] has one permutation, output it\r\n                  copy(list, list+m+1,\r\n                       ostream_iterator<T>(cout, \"\"));\r\n                  cout << endl;\r\n                }\r\n   else  // list[k:m] has more than one permutation\r\n         // generate these recursively \r\n         for (i = k; i <= m; i++)\r\n         {\r\n            swap(list[k], list[i]);\r\n            permutations(list, k+1, m);\r\n            swap(list[k], list[i]);\r\n         }\r\n}\r\n\r\nint main()\r\n{\r\n   char a[] = {'1', '2', '3', '4'};\r\n\r\n   cout << \"The permutations of 1 are\" << endl;\r\n   permutations(a, 0, 0);\r\n\r\n   cout << \"The permutations of 123 are\" << endl;\r\n   permutations(a, 0, 2);\r\n\r\n   cout << \"The permutations of 1234 are\" << endl;\r\n   permutations(a, 0, 3);\r\n   return 0;\r\n}\r\n"
