    "code": "// compute element ranks\r\n\r\n#include <iostream>\r\n#include <algorithm> // has copy\r\n\r\nusing namespace std;\r\n\r\n\r\ntemplate<class T>\r\nvoid rank(T a[], int n, int r[])\r\n{// Rank the n elements a[0:n-1].\r\n // Element ranks returned in r[0:n-1]\r\n   for (int i = 0; i < n; i++)\r\n      r[i] = 0;  // initialize\r\n\r\n   // compare all element pairs\r\n   for (int i = 1; i < n; i++)\r\n      for (int j = 0; j < i; j++)\r\n         if (a[j] <= a[i]) r[i]++;\r\n         else r[j]++;\r\n}\r\n\r\nint main()\r\n{\r\n   int a[6] = {2, 6, 4, 3, 1, 5};\r\n   int r[6];\r\n\r\n   // output the elements\r\n   cout << \"a[0:5] = \";\r\n   copy(a, a+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   // determine the ranks\r\n   rank(a,6,r);\r\n\r\n   // output the ranks\r\n   cout << \"r[0:5] = \";\r\n   copy(r, r+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n   return 0;\r\n}\r\n"
