    "code": "// rank or count sort\r\n// rearrange elements using an additioal array\r\n\r\n#include <iostream>\r\n#include <algorithm> // has copy\r\n\r\nusing namespace std;\r\n\r\n\r\ntemplate<class T>\r\nvoid rearrange(T a[], int n, int r[])\r\n{// Rearrange the elements of a into sorted order\r\n // using an additional array u.\r\n   T *u = new T [n]; // create additional array\r\n\r\n   // move to correct place in u\r\n   for (int i = 0; i < n; i++)\r\n      u[r[i]] = a[i];\r\n\r\n   // move back to a\r\n   for (i = 0; i < n; i++)\r\n      a[i] = u[i];\r\n\r\n   delete [] u;\r\n}\r\n\r\ntemplate<class T>\r\nvoid rank(T a[], int n, int r[])\r\n{// Rank the n elements a[0:n-1].\r\n // Element ranks returned in r[0:n-1]\r\n   for (int i = 0; i < n; i++)\r\n      r[i] = 0;  // initialize\r\n\r\n   // compare all element pairs\r\n   for (int i = 1; i < n; i++)\r\n      for (int j = 0; j < i; j++)\r\n         if (a[j] <= a[i]) r[i]++;\r\n         else r[j]++;\r\n}\r\n\r\nint main()\r\n{\r\n   int a[6] = {2, 6, 4, 3, 1, 5};\r\n   int r[6];\r\n\r\n   // output the elements\r\n   cout << \"a[0:5] = \";\r\n   copy(a, a+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   // sort\r\n   rank(a,6,r);\r\n   rearrange(a,6,r);\r\n\r\n   // output the sorted sequence\r\n   cout << \"After the sort, a[0:5] = \";\r\n   copy(a, a+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n   return 0;\r\n}\r\n"
