    "code": "// insert into a sorted array\r\n\r\n#include <iostream>\r\n#include <algorithm> // has copy\r\n\r\nusing namespace std;\r\n\r\n\r\ntemplate<class T>\r\nvoid insert(T a[], int& n, const T& x)\r\n{// Insert x into the sorted array a[0:n-1].\r\n // Assume a is of size > n \r\n   int i;\r\n   for (i = n-1; i >= 0 && x < a[i]; i--)\r\n      a[i+1] = a[i];\r\n   a[i+1] = x;\r\n   n++; // one element added to a\r\n}\r\n\r\nint main()\r\n{\r\n   int a[10] = {1, 2, 4, 6, 8, 10, 12, 0, 0, 0};\r\n   int x; // element to be inserted\r\n   int n = 7;\r\n\r\n   // output the elements\r\n   cout << \"a[0:6] = \";\r\n   copy(a, a+n, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   // do a few inserts\r\n   x = 14;\r\n   insert(a,n,x);\r\n   cout << \"After inserting 14, a[0:7] = \";\r\n   copy(a, a+n, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   x = 5;\r\n   insert(a,n,x);\r\n   cout << \"After inserting 5, a[0:8] = \";\r\n   copy(a, a+n, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   x = 0;\r\n   insert(a,n,x);\r\n   cout << \"After inserting 0, a[0:9] = \";\r\n   copy(a, a+n, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   return 0;\r\n}\r\n"
