    "code": "// rank sort without additional array\r\n#include <iostream>\r\n#include <algorithm> // has copy\r\n\r\nusing namespace std;\r\n\r\n\r\ntemplate<class T>\r\nvoid rearrange(T a[], int n, int r[])\r\n{// In-place rearrangement into sorted order.\r\n   for (int i = 0; i < n; i++)\r\n      // get proper element to a[i]\r\n      while (r[i] != i)\r\n      {\r\n         int t = r[i];\r\n         swap(a[i], a[t]);\r\n         swap(r[i], r[t]);\r\n      }\r\n}\r\n\r\ntemplate<class T>\r\nvoid rank(T a[], int n, int r[])\r\n{// Rank the n elements a[0:n-1].\r\n // Element ranks returned in r[0:n-1]\r\n   for (int i = 0; i < n; i++)\r\n      r[i] = 0;  // initialize\r\n\r\n   // compare all element pairs\r\n   for (int i = 1; i < n; i++)\r\n      for (int j = 0; j < i; j++)\r\n         if (a[j] <= a[i]) r[i]++;\r\n         else r[j]++;\r\n}\r\n\r\nint main()\r\n{\r\n   int a[6] = {2, 6, 4, 3, 1, 5};\r\n   int r[6];\r\n\r\n   // output the elements\r\n   cout << \"a[0:5] = \";\r\n   copy(a, a+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   // sort\r\n   rank(a,6,r);\r\n   rearrange(a,6,r);\r\n\r\n   // output the sorted sequence\r\n   cout << \"After the sort, a[0:5] = \";\r\n   copy(a, a+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n   return 0;\r\n}\r\n"
