    "code": "// early terminating bubble sort\r\n\r\n#include <iostream>\r\n#include <algorithm> // has copy\r\n\r\nusing namespace std;\r\n\r\n\r\ntemplate<class T>\r\nbool bubble(T a[], int n)\r\n{// Bubble largest element in a[0:n-1] to right.\r\n   bool swapped = false; // no swaps so far\r\n   for (int i = 0; i < n - 1; i++)\r\n      if (a[i] > a[i+1])\r\n      {\r\n         swap(a[i], a[i + 1]);\r\n         swapped = true; // swap was done\r\n      }\r\n   return swapped;\r\n}\r\n\r\ntemplate<class T>\r\nvoid bubbleSort(T a[], int n)\r\n{// Early-terminating version of bubble sort.\r\n   for (int i = n; i > 1 && bubble(a, i); i--);\r\n}\r\n\r\nint main()\r\n{\r\n   int a[10] = {10,9,1,2,3,4,8,7,6,5};\r\n\r\n   // output the elements\r\n   cout << \"a[0:9] = \";\r\n   copy(a, a+10, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   // sort\r\n   bubbleSort(a,10);\r\n\r\n   // output the sorted sequence\r\n   cout << \"After the sort, a[0:9] = \";\r\n   copy(a, a+10, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n   return 0;\r\n}\r\n"
