    "code": "// ineffficient prefix sums\r\n\r\n#include <iostream>\r\n#include <algorithm>\r\n\r\nusing namespace std;\r\n\r\ntemplate <class T>\r\nT sum(T a[], int n)\r\n{// Return sum of numbers a[0:n - 1].\r\n   T theSum = 0;\r\n   for (int i = 0; i < n; i++)\r\n      theSum += a[i];\r\n   return theSum;\r\n}\r\n\r\ntemplate <class T>\r\nvoid inef(T a[], T b[], int n)\r\n{// Compute prefix sums.\r\n   for (int j = 0; j < n; j++)\r\n      b[j] = sum(a, j + 1);\r\n}\r\n\r\nint main()\r\n{\r\n   int a[6] = {1, 2, 3, 4, 5, 6};\r\n   int b[6];\r\n   int n = 6;\r\n\r\n   // output the array elements\r\n   cout << \"a[0:5] = \";\r\n   copy(a, a+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n\r\n   // compute the prefix sums inefficiently\r\n   inef(a,b,n);\r\n\r\n   // output the prefix sums\r\n   cout << \"The prefix sums are \";\r\n   copy(b, b+6, ostream_iterator<int>(cout, \" \"));\r\n   cout << endl;\r\n}\r\n"
