    "code": "// multipy square matrices\r\n\r\n#include <iostream>\r\n#include \"make2dArrayNoCatch.h\"\r\n\r\nusing namespace std;\r\n\r\ntemplate<class T>\r\nvoid squareMatrixMultiply(T **a, T **b, T **c, int n)\r\n{// Multiply the n x n matrices a and b to get c.\r\n   for (int i = 0; i < n; i++)\r\n      for (int j = 0; j < n; j++)\r\n      {\r\n         T sum = 0;\r\n         for (int k = 0; k < n; k++)\r\n            sum += a[i][k] * b[k][j];\r\n         c[i][j] = sum;\r\n      }\r\n}\r\n\r\nint main()\r\n{\r\n   int **a, **b, **c;\r\n   make2dArray(a,2,2);\r\n   make2dArray(b,2,2);\r\n   make2dArray(c,2,2);\r\n\r\n   a[0][0] = 1; a[0][1] = 2; a[1][0] = 3; a[1][1] = 4;\r\n   b[0][0] = 5; b[0][1] = 6; b[1][0] = 1; b[1][1] = 2;\r\n\r\n   cout << \"The first matrix is\" << endl;\r\n   cout << a[0][0] << ' ' << a[0][1] << endl;\r\n   cout << a[1][0] << ' ' << a[1][1] << endl;\r\n\r\n   cout << \"The second matrix is\" << endl;\r\n   cout << b[0][0] << ' ' << b[0][1] << endl;\r\n   cout << b[1][0] << ' ' << b[1][1] << endl;\r\n\r\n   squareMatrixMultiply(a,b,c,2);\r\n\r\n   cout << \"Their product is\" << endl;\r\n   cout << c[0][0] << ' ' << c[0][1] << endl;\r\n   cout << c[1][0] << ' ' << c[1][1] << endl;\r\n\r\n   return 0;\r\n}\r\n"
