    "code": "// another code to multiply square matrices\r\n\r\n#include <iostream>\r\n#include \"make2dArrayNoCatch.h\"\r\n\r\nusing namespace std;\r\n\r\nvoid fastSquareMatrixMultiply(int ** a, int ** b, int ** c, int n)\r\n{\r\n   for (int i = 0; i < n; i++)\r\n      for (int j = 0; j < n; j++)\r\n         c[i][j] = 0;\r\n\r\n   for (int i = 0; i < n; i++)\r\n      for (int j = 0; j < n; j++)\r\n         for (int k = 0; k < n; k++)\r\n            c[i][j] += a[i][k] * b[k][j];\r\n}\r\n\r\n\r\nint main()\r\n{\r\n   int **a, **b, **c;\r\n   make2dArray(a,2,2);\r\n   make2dArray(b,2,2);\r\n   make2dArray(c,2,2);\r\n\r\n   a[0][0] = 1; a[0][1] = 2; a[1][0] = 3; a[1][1] = 4;\r\n   b[0][0] = 5; b[0][1] = 6; b[1][0] = 1; b[1][1] = 2;\r\n\r\n   cout << \"The first matrix is\" << endl;\r\n   cout << a[0][0] << ' ' << a[0][1] << endl;\r\n   cout << a[1][0] << ' ' << a[1][1] << endl;\r\n\r\n   cout << \"The second matrix is\" << endl;\r\n   cout << b[0][0] << ' ' << b[0][1] << endl;\r\n   cout << b[1][0] << ' ' << b[1][1] << endl;\r\n\r\n   fastSquareMatrixMultiply(a,b,c,2);\r\n\r\n   cout << \"Their product is\" << endl;\r\n   cout << c[0][0] << ' ' << c[0][1] << endl;\r\n   cout << c[1][0] << ' ' << c[1][1] << endl;\r\n\r\n   return 0;\r\n}\r\n"
