    "code": "// linked implementation of a linear list\r\n// derives from abstract class linearList just to make sure\r\n// all methods of the ADT are implemented\r\n// unidirectional iterator for chain included\r\n\r\n#ifndef chain_\r\n#define chain_\r\n\r\n#include <iostream>\r\n#include <sstream>\r\n#include <string>\r\n#include \"linearList.h\"\r\n#include \"chainNode.h\"\r\n#include \"myExceptions.h\"\r\n\r\nusing namespace std;\r\n\r\nclass linkedDigraph;\r\ntemplate <class T> class linkedWDigraph;\r\n\r\ntemplate<class T>\r\nclass chain : public linearList<T> \r\n{\r\n   friend linkedDigraph;\r\n   friend linkedWDigraph<int>;\r\n   friend linkedWDigraph<float>;\r\n   friend linkedWDigraph<double>;\r\n   public:\r\n      // constructor, copy constructor and destructor\r\n      chain(int initialCapacity = 10);\r\n      chain(const chain<T>&);\r\n      ~chain();\r\n\r\n      // ADT methods\r\n      bool empty() const {return listSize == 0;}\r\n      int size() const {return listSize;}\r\n      T& get(int theIndex) const;\r\n      int indexOf(const T& theElement) const;\r\n      void erase(int theIndex);\r\n      void insert(int theIndex, const T& theElement);\r\n      void output(ostream& out) const;\r\n      \r\n      // iterators to start and end of list\r\n      class iterator;\r\n      iterator begin() {return iterator(firstNode);}\r\n      iterator end() {return iterator(NULL);}\r\n\r\n      // iterator for chain\r\n      class iterator \r\n      {\r\n         public:\r\n            // typedefs required by C++ for a forward iterator\r\n            typedef forward_iterator_tag iterator_category;\r\n            typedef T value_type;\r\n            typedef ptrdiff_t difference_type;\r\n            typedef T* pointer;\r\n            typedef T& reference;\r\n\r\n            // constructor\r\n            iterator(chainNode<T>* theNode = NULL)\r\n               {node = theNode;}\r\n\r\n            // dereferencing operators\r\n            T& operator*() const {return node->element;}\r\n            T* operator->() const {return &node->element;}\r\n\r\n            // increment\r\n            iterator& operator++()   // preincrement\r\n                      {node = node->next; return *this;}\r\n            iterator operator++(int) // postincrement\r\n            \t      {iterator old = *this;\r\n            \t       node = node->next;\r\n            \t       return old;\r\n            \t      }\r\n\r\n            // equality testing\r\n            bool operator!=(const iterator right) const\r\n                  {return node != right.node;}\r\n            bool operator==(const iterator right) const\r\n                  {return node == right.node;}\r\n         protected:\r\n            chainNode<T>* node;\r\n      };  // end of iterator class\r\n\r\n   protected:\r\n      void checkIndex(int theIndex) const;\r\n            // throw illegalIndex if theIndex invalid\r\n      chainNode<T>* firstNode;  // pointer to first node in chain\r\n      int listSize;             // number of elements in list\r\n};\r\n\r\ntemplate<class T>\r\nchain<T>::chain(int initialCapacity)\r\n{// Constructor.\r\n   if (initialCapacity < 1)\r\n   {ostringstream s;\r\n    s << \"Initial capacity = \" << initialCapacity << \" Must be > 0\";\r\n    throw illegalParameterValue(s.str());\r\n   }\r\n   firstNode = NULL;\r\n   listSize = 0;\r\n}\r\n\r\ntemplate<class T>\r\nchain<T>::chain(const chain<T>& theList)\r\n{// Copy constructor.\r\n   listSize = theList.listSize;\r\n\r\n   if (listSize == 0)\r\n   {// theList is empty\r\n      firstNode = NULL;\r\n      return;\r\n   }\r\n\r\n   // non-empty list\r\n   chainNode<T>* sourceNode = theList.firstNode;\r\n                    // node in theList to copy from\r\n   firstNode = new chainNode<T>(sourceNode->element);\r\n                    // copy first element of theList\r\n   sourceNode = sourceNode->next;\r\n   chainNode<T>* targetNode = firstNode;\r\n                    // current last node in *this\r\n   while (sourceNode != NULL)\r\n   {// copy remaining elements\r\n      targetNode->next = new chainNode<T>(sourceNode->element);\r\n      targetNode = targetNode->next;\r\n      sourceNode = sourceNode->next;\r\n   }\r\n   targetNode->next = NULL; // end the chain\r\n}\r\n\r\ntemplate<class T>\r\nchain<T>::~chain()\r\n{// Chain destructor. Delete all nodes in chain.\r\n   chainNode<T> *nextNode;\r\n   while (firstNode != NULL)\r\n   {// delete firstNode\r\n      nextNode = firstNode->next;\r\n      delete firstNode;\r\n      firstNode = nextNode;\r\n   }\r\n}\r\n\r\ntemplate<class T>\r\nvoid chain<T>::checkIndex(int theIndex) const\r\n{// Verify that theIndex is between 0 and listSize - 1.\r\n   if (theIndex < 0 || theIndex >= listSize)\r\n   {ostringstream s;\r\n    s << \"index = \" << theIndex << \" size = \" << listSize;\r\n    throw illegalIndex(s.str());\r\n   }\r\n}\r\n\r\ntemplate<class T>\r\nT& chain<T>::get(int theIndex) const\r\n{// Return element whose index is theIndex.\r\n // Throw illegalIndex exception if no such element.\r\n   checkIndex(theIndex);\r\n\r\n   // move to desired node\r\n   chainNode<T>* currentNode = firstNode;\r\n   for (int i = 0; i < theIndex; i++)\r\n      currentNode = currentNode->next;\r\n\r\n   return currentNode->element;\r\n}\r\n\r\ntemplate<class T>\r\nint chain<T>::indexOf(const T& theElement) const\r\n{// Return index of first occurrence of theElement.\r\n // Return -1 if theElement not in list.\r\n\r\n   // search the chain for theElement\r\n   chainNode<T>* currentNode = firstNode;\r\n   int index = 0;  // index of currentNode\r\n   while (currentNode != NULL && \r\n          currentNode->element != theElement)\r\n   {\r\n      // move to next node\r\n      currentNode = currentNode->next;\r\n      index++;\r\n   }\r\n\r\n   // make sure we found matching element\r\n   if (currentNode == NULL)\r\n      return -1;\r\n   else\r\n      return index;\r\n}\r\n\r\ntemplate<class T>\r\nvoid chain<T>::erase(int theIndex)\r\n{// Delete the element whose index is theIndex.\r\n // Throw illegalIndex exception if no such element.\r\n   checkIndex(theIndex);\r\n\r\n   // valid index, locate node with element to delete\r\n   chainNode<T>* deleteNode;\r\n   if (theIndex == 0)\r\n   {// remove first node from chain\r\n      deleteNode = firstNode;\r\n      firstNode = firstNode->next;\r\n   }\r\n   else \r\n   {  // use p to get to predecessor of desired node\r\n      chainNode<T>* p = firstNode;\r\n      for (int i = 0; i < theIndex - 1; i++)\r\n         p = p->next;\r\n   \r\n      deleteNode = p->next;\r\n      p->next = p->next->next; // remove deleteNode from chain\r\n   }\r\n   listSize--;\r\n   delete deleteNode;\r\n}\r\n\r\ntemplate<class T>\r\nvoid chain<T>::insert(int theIndex, const T& theElement)\r\n{// Insert theElement so that its index is theIndex.\r\n   if (theIndex < 0 || theIndex > listSize)\r\n   {// invalid index\r\n      ostringstream s;\r\n      s << \"index = \" << theIndex << \" size = \" << listSize;\r\n      throw illegalIndex(s.str());\r\n   }\r\n\r\n   if (theIndex == 0)\r\n      // insert at front\r\n      firstNode = new chainNode<T>(theElement, firstNode);\r\n   else\r\n   {  // find predecessor of new element\r\n      chainNode<T>* p = firstNode;\r\n      for (int i = 0; i < theIndex - 1; i++)\r\n         p = p->next;\r\n   \r\n      // insert after p\r\n      p->next = new chainNode<T>(theElement, p->next);\r\n   }\r\n   listSize++;\r\n}\r\n\r\ntemplate<class T>\r\nvoid chain<T>::output(ostream& out) const\r\n{// Put the list into the stream out.\r\n   for (chainNode<T>* currentNode = firstNode;\r\n                      currentNode != NULL;\r\n                      currentNode = currentNode->next)\r\n      out << currentNode->element << \"  \";\r\n}\r\n\r\n// overload <<\r\ntemplate <class T>\r\nostream& operator<<(ostream& out, const chain<T>& x)\r\n   {x.output(out); return out;}\r\n\r\n#endif\r\n"
