    "code": "\r\n// linked implementation of a queue\r\n// derives from the ADT queue\r\n\r\n#ifndef linkedQueue_\r\n#define linkedQueue_\r\n\r\n#include \"queue.h\"\r\n#include \"chainNode.h\"\r\n#include \"myExceptions.h\"\r\n#include <sstream>\r\n\r\nusing namespace std;\r\n\r\ntemplate<class T>\r\nclass linkedQueue : public queue<T>\r\n{\r\n   public:\r\n      linkedQueue(int initialCapacity = 10)\r\n            {queueFront = NULL; queueSize = 0;}\r\n      ~linkedQueue();\r\n      bool empty() const \r\n           {return queueSize == 0;}\r\n      int size() const\r\n          {return queueSize;}\r\n      T& front()\r\n         {\r\n            if (queueSize == 0)\r\n               throw queueEmpty();\r\n            return queueFront->element;\r\n         }\r\n      T& back()\r\n         {\r\n            if (queueSize == 0)\r\n               throw queueEmpty();\r\n            return queueBack->element;\r\n         }\r\n      void pop();\r\n      void push(const T&);\r\n   private:\r\n      chainNode<T>* queueFront;  // pointer to queue front\r\n      chainNode<T>* queueBack;   // pointer to queue back\r\n      int queueSize;             // number of elements in queue\r\n};\r\n\r\ntemplate<class T>\r\nlinkedQueue<T>::~linkedQueue()\r\n{// Destructor.\r\n   while (queueFront != NULL)\r\n   {// delete front node\r\n      chainNode<T>* nextNode = queueFront->next;\r\n      delete queueFront;\r\n      queueFront = nextNode;\r\n   }\r\n}\r\n\r\ntemplate<class T>\r\nvoid linkedQueue<T>::pop()\r\n{// Delete front element.\r\n   if (queueFront == NULL)\r\n      throw queueEmpty();\r\n\r\n   chainNode<T>* nextNode = queueFront->next;\r\n   delete queueFront;\r\n   queueFront = nextNode;\r\n   queueSize--;\r\n}\r\n\r\n\r\ntemplate<class T>\r\nvoid linkedQueue<T>::push(const T& theElement)\r\n{// Add theElement to back of queue.\r\n\r\n   // create node for new element\r\n   chainNode<T>* newNode = new chainNode<T>(theElement, NULL);\r\n\r\n   // add new node to back of queue\r\n   if (queueSize == 0)\r\n      queueFront = newNode;       // queue empty\r\n   else \r\n      queueBack->next = newNode;  // queue not empty\r\n   queueBack = newNode;\r\n\r\n   queueSize++;\r\n}\r\n#endif\r\n"
