    "code": "// heap sort a[1:n]\r\n#ifndef heapSort_\r\n#define heapSort_\r\n\r\n#include \"maxHeap.h\"\r\n\r\nusing namespace std;\r\n\r\ntemplate <class T>\r\nvoid heapSort(T a[], int n)\r\n{// Sort a[1:n] using the heap sort method.\r\n   // create a max heap of the elements\r\n   maxHeap<T> heap(1);\r\n   heap.initialize(a, n);\r\n\r\n   // extract one by one from the max heap\r\n   for (int i = n - 1; i >= 1; i--)\r\n   {\r\n      T x = heap.top();\r\n      heap.pop();\r\n      a[i+1] = x;\r\n   }\r\n\r\n   // save array a from heap destructor\r\n   heap.deactivateArray();\r\n}\r\n\r\n#endif\r\n"
